#Requires -Version 7.2
[CmdletBinding()]
param(
  [ValidateSet('Plan','Verify')][string]$Action='Plan',
  [string]$LegacyBaselineEvidencePath,[string]$ExpectedLegacyBaselineEvidenceSha256,
  [string]$LegacyQuiesceEvidencePath,[string]$ExpectedLegacyQuiesceEvidenceSha256,
  [string]$TargetReleaseRoot,[string]$ExpectedTargetManifestSha256,
  [string]$RestoreEvidencePath,[string]$ExpectedRestoreEvidenceSha256,
  [string]$RehearsalEvidencePath,[string]$ExpectedRehearsalEvidenceSha256,
  [string]$LatestBackupEvidencePath,[string]$ExpectedLatestBackupEvidenceSha256,
  [string]$QuiesceReceiptPublicKeyPath,[string]$ExpectedQuiesceReceiptPublicKeySha256,
  [string]$RestoreReceiptPublicKeyPath,[string]$ExpectedRestoreReceiptPublicKeySha256,
  [string]$BackupReceiptPublicKeyPath,[string]$ExpectedBackupReceiptPublicKeySha256,[string]$NodePath,[string]$ExpectedNodeSha256,
  [string]$AttestationVerifierPath,[string]$ExpectedAttestationVerifierSha256,
  [string]$EvidenceOutputPath,[ValidateSet('VerifyEvidence')][string]$PlannedAction,[string]$ApprovedPlanSha256,[string]$ApprovalNonce,[string]$ApprovalIssuedAt,[string]$ApprovalExpiresAt,[string]$ApprovalInstanceId,[string]$ApprovalLedgerPath,[switch]$Approved
)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'approval-plan.ps1')
function Existing([string]$Path,[bool]$Directory,[string]$Code){$kind=if($Directory){'Container'}else{'Leaf'};if(-not$Path-or-not(Test-Path -LiteralPath $Path -PathType $kind)){throw $Code};$full=[IO.Path]::GetFullPath($Path).TrimEnd('\');$cursor=Get-Item -LiteralPath $full -Force;while($cursor){if($cursor.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'INITIAL_CUTOVER_REPARSE_REJECTED'};$cursor=$cursor.Parent};return $full}
function Hash([string]$Path){return(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function AssertHash([string]$Path,[string]$Expected,[string]$Code){if($Expected-notmatch'^[A-Fa-f0-9]{64}$'-or(Hash $Path)-cne$Expected.ToLowerInvariant()){throw $Code}}
function VerifyReceipt([string]$PublicKey,[string]$Path,[string]$Type,[string]$Code){&$node $verifier $PublicKey $Path $Type 2>$null|Out-Null;if($LASTEXITCODE-ne0){throw $Code}}

function New-InitialCutoverApprovalPlan([string]$IntendedAction){
  if($IntendedAction-cne'VerifyEvidence'){throw 'INITIAL_CUTOVER_PLAN_ACTION_REQUIRED'}
  $p=[ordered]@{
    legacyBaselineEvidencePath=Get-ApprovalPath $LegacyBaselineEvidencePath 'INITIAL_CUTOVER_PLAN_BASELINE_REQUIRED';legacyBaselineEvidenceSha256=Get-ApprovalHash $ExpectedLegacyBaselineEvidenceSha256 'INITIAL_CUTOVER_PLAN_BASELINE_HASH_REQUIRED'
    legacyQuiesceEvidencePath=Get-ApprovalPath $LegacyQuiesceEvidencePath 'INITIAL_CUTOVER_PLAN_QUIESCE_REQUIRED';legacyQuiesceEvidenceSha256=Get-ApprovalHash $ExpectedLegacyQuiesceEvidenceSha256 'INITIAL_CUTOVER_PLAN_QUIESCE_HASH_REQUIRED'
    targetReleaseRoot=Get-ApprovalPath $TargetReleaseRoot 'INITIAL_CUTOVER_PLAN_TARGET_REQUIRED';targetManifestSha256=Get-ApprovalHash $ExpectedTargetManifestSha256 'INITIAL_CUTOVER_PLAN_TARGET_HASH_REQUIRED'
    restoreEvidencePath=Get-ApprovalPath $RestoreEvidencePath 'INITIAL_CUTOVER_PLAN_RESTORE_REQUIRED';restoreEvidenceSha256=Get-ApprovalHash $ExpectedRestoreEvidenceSha256 'INITIAL_CUTOVER_PLAN_RESTORE_HASH_REQUIRED'
    rehearsalEvidencePath=Get-ApprovalPath $RehearsalEvidencePath 'INITIAL_CUTOVER_PLAN_REHEARSAL_REQUIRED';rehearsalEvidenceSha256=Get-ApprovalHash $ExpectedRehearsalEvidenceSha256 'INITIAL_CUTOVER_PLAN_REHEARSAL_HASH_REQUIRED'
    latestBackupEvidencePath=Get-ApprovalPath $LatestBackupEvidencePath 'INITIAL_CUTOVER_PLAN_BACKUP_REQUIRED';latestBackupEvidenceSha256=Get-ApprovalHash $ExpectedLatestBackupEvidenceSha256 'INITIAL_CUTOVER_PLAN_BACKUP_HASH_REQUIRED'
    quiesceReceiptPublicKeyPath=Get-ApprovalPath $QuiesceReceiptPublicKeyPath 'INITIAL_CUTOVER_PLAN_QUIESCE_PUBLIC_KEY_REQUIRED';quiesceReceiptPublicKeySha256=Get-ApprovalHash $ExpectedQuiesceReceiptPublicKeySha256 'INITIAL_CUTOVER_PLAN_QUIESCE_PUBLIC_KEY_HASH_REQUIRED'
    restoreReceiptPublicKeyPath=Get-ApprovalPath $RestoreReceiptPublicKeyPath 'INITIAL_CUTOVER_PLAN_RESTORE_PUBLIC_KEY_REQUIRED';restoreReceiptPublicKeySha256=Get-ApprovalHash $ExpectedRestoreReceiptPublicKeySha256 'INITIAL_CUTOVER_PLAN_RESTORE_PUBLIC_KEY_HASH_REQUIRED'
    backupReceiptPublicKeyPath=Get-ApprovalPath $BackupReceiptPublicKeyPath 'INITIAL_CUTOVER_PLAN_BACKUP_PUBLIC_KEY_REQUIRED';backupReceiptPublicKeySha256=Get-ApprovalHash $ExpectedBackupReceiptPublicKeySha256 'INITIAL_CUTOVER_PLAN_BACKUP_PUBLIC_KEY_HASH_REQUIRED'
    nodePath=Get-ApprovalPath $NodePath 'INITIAL_CUTOVER_PLAN_NODE_REQUIRED';nodeSha256=Get-ApprovalHash $ExpectedNodeSha256 'INITIAL_CUTOVER_PLAN_NODE_HASH_REQUIRED';attestationVerifierPath=Get-ApprovalPath $AttestationVerifierPath 'INITIAL_CUTOVER_PLAN_VERIFIER_REQUIRED';attestationVerifierSha256=Get-ApprovalHash $ExpectedAttestationVerifierSha256 'INITIAL_CUTOVER_PLAN_VERIFIER_HASH_REQUIRED';evidenceOutputPath=Get-ApprovalPath $EvidenceOutputPath 'INITIAL_CUTOVER_PLAN_OUTPUT_REQUIRED'
  }
  New-ApprovalPlan $PSCommandPath 'VerifyEvidence' $p 'Exact quiesced legacy baseline, type-separated signed prechange backup/restore/rehearsal, target manifest, and cutover evidence output' 'Performs read-only compatibility and rollback-contract checks and writes one non-secret first-cutover receipt' 'Delete only the exact compatibility receipt; operational rollback remains signed DB restore plus exact legacy restart'
}
if($Action-eq'Plan'){New-InitialCutoverApprovalPlan $PlannedAction|ConvertTo-Json -Depth 12;exit 0};if($EvidenceOutputPath){$approvalPlan=New-InitialCutoverApprovalPlan 'VerifyEvidence';Assert-ApprovedPlan $approvalPlan ([bool]$Approved) $ApprovedPlanSha256}
$baselinePath=Existing $LegacyBaselineEvidencePath $false 'LEGACY_BASELINE_NOT_FOUND';$quiescePath=Existing $LegacyQuiesceEvidencePath $false 'LEGACY_QUIESCE_EVIDENCE_NOT_FOUND';$targetRoot=Existing $TargetReleaseRoot $true 'TARGET_RELEASE_NOT_FOUND';$targetManifestPath=Existing (Join-Path $targetRoot 'release-manifest.json') $false 'TARGET_MANIFEST_NOT_FOUND';$restorePath=Existing $RestoreEvidencePath $false 'RESTORE_EVIDENCE_NOT_FOUND';$rehearsalPath=Existing $RehearsalEvidencePath $false 'REHEARSAL_EVIDENCE_NOT_FOUND';$backupPath=Existing $LatestBackupEvidencePath $false 'LATEST_BACKUP_EVIDENCE_NOT_FOUND';$quiescePublic=Existing $QuiesceReceiptPublicKeyPath $false 'QUIESCE_PUBLIC_KEY_NOT_FOUND';$restorePublic=Existing $RestoreReceiptPublicKeyPath $false 'RESTORE_PUBLIC_KEY_NOT_FOUND';$backupPublic=Existing $BackupReceiptPublicKeyPath $false 'BACKUP_PUBLIC_KEY_NOT_FOUND';$node=Existing $NodePath $false 'NODE_NOT_FOUND';$verifier=Existing $AttestationVerifierPath $false 'ATTESTATION_VERIFIER_NOT_FOUND'
AssertHash $baselinePath $ExpectedLegacyBaselineEvidenceSha256 'LEGACY_BASELINE_HASH_MISMATCH';AssertHash $quiescePath $ExpectedLegacyQuiesceEvidenceSha256 'LEGACY_QUIESCE_EVIDENCE_HASH_MISMATCH';AssertHash $targetManifestPath $ExpectedTargetManifestSha256 'TARGET_MANIFEST_HASH_MISMATCH';AssertHash $restorePath $ExpectedRestoreEvidenceSha256 'RESTORE_EVIDENCE_HASH_MISMATCH';AssertHash $rehearsalPath $ExpectedRehearsalEvidenceSha256 'REHEARSAL_EVIDENCE_HASH_MISMATCH';AssertHash $backupPath $ExpectedLatestBackupEvidenceSha256 'LATEST_BACKUP_EVIDENCE_HASH_MISMATCH';AssertHash $quiescePublic $ExpectedQuiesceReceiptPublicKeySha256 'QUIESCE_PUBLIC_KEY_HASH_MISMATCH';AssertHash $restorePublic $ExpectedRestoreReceiptPublicKeySha256 'RESTORE_PUBLIC_KEY_HASH_MISMATCH';AssertHash $backupPublic $ExpectedBackupReceiptPublicKeySha256 'BACKUP_PUBLIC_KEY_HASH_MISMATCH';AssertHash $node $ExpectedNodeSha256 'NODE_HASH_MISMATCH';AssertHash $verifier $ExpectedAttestationVerifierSha256 'ATTESTATION_VERIFIER_HASH_MISMATCH'
VerifyReceipt $quiescePublic $quiescePath 'legacy-quiesce' 'LEGACY_QUIESCE_SIGNATURE_REJECTED';VerifyReceipt $restorePublic $restorePath 'restore-verification' 'RESTORE_SIGNATURE_REJECTED';VerifyReceipt $restorePublic $rehearsalPath 'release-compatibility' 'REHEARSAL_SIGNATURE_REJECTED';VerifyReceipt $backupPublic $backupPath 'backup-latest' 'BACKUP_SIGNATURE_REJECTED'
$baseline=Get-Content -Raw -LiteralPath $baselinePath|ConvertFrom-Json;$quiesce=Get-Content -Raw -LiteralPath $quiescePath|ConvertFrom-Json;$target=Get-Content -Raw -LiteralPath $targetManifestPath|ConvertFrom-Json;$restore=Get-Content -Raw -LiteralPath $restorePath|ConvertFrom-Json;$rehearsal=Get-Content -Raw -LiteralPath $rehearsalPath|ConvertFrom-Json;$backup=Get-Content -Raw -LiteralPath $backupPath|ConvertFrom-Json
if(@(Get-NetTCPConnection -State Listen -LocalPort 3100,4100 -ErrorAction SilentlyContinue).Count-or(Get-Process -Id ([int]$baseline.webProcessId),([int]$baseline.apiProcessId) -ErrorAction SilentlyContinue)){throw 'LEGACY_QUIESCE_STATE_CHANGED'}
$now=(Get-Date).ToUniversalTime();$backupAt=[datetime]::Parse([string]$backup.completedAt).ToUniversalTime();$restoreAt=[datetime]::Parse([string]$restore.completedAt).ToUniversalTime();$rehearsalAt=[datetime]::Parse([string]$rehearsal.completedAt).ToUniversalTime();$quiesceAt=[datetime]::Parse([string]$quiesce.completedAt).ToUniversalTime();$digestInvalid=@(@($rehearsal.previousBusinessBeforeDigest,$rehearsal.previousBusinessAfterDigest,$rehearsal.targetBusinessAfterDigest,$rehearsal.targetRoleMatrixAfterDigest,$rehearsal.targetAppliedMigrationDigest)|Where-Object{$_-notmatch'^[0-9a-f]{64}$'}).Count-gt0
if($baseline.version-ne3-or-not$baseline.launchIdentityMatchesProtectedRestartSpec-or-not$baseline.legacyIdentityHealthSmokeVerified-or$baseline.proofType-cne'legacy-running-baseline'-or$baseline.legacyStorageProvider-cne'repository_local_ntfs'-or$baseline.localReleaseManifestApplicable-or-not$baseline.referenceConversionRequired-or$quiesce.version-ne2-or$quiesce.result-cne'PASS'-or$quiesce.baselineSha256-cne(Hash $baselinePath)-or$quiesce.restartCanonicalDigest-cne$baseline.restartCanonicalDigest-or-not$quiesce.legacyIdentityHealthSmokeVerifiedBeforeStop-or-not$quiesce.processesStopped-or-not$quiesce.listenersAbsent-or$quiesce.databaseMutated-or$target.version-ne3-or$backup.backupMode-cne'LEGACY_BASELINE'-or$backup.legacyBaselineSha256-cne(Hash $baselinePath)-or$backup.storageReferenceConversionSha256-notmatch'^[0-9a-f]{64}$'-or([bool]$backup.storageReferenceZeroVerified-ne($backup.storageReferenceCount-eq0))-or$restore.version-ne6-or$restore.result-ne'PASS'-or$restore.backupMode-cne'LEGACY_BASELINE'-or-not$restore.storageReferenceConversionVerified-or$restore.storageReferenceCount-ne$backup.storageReferenceCount-or$restore.releaseId-cne$baseline.releaseId-or$restore.migrationDigest-cne$baseline.migrationDigest-or$restore.backupId-cne$backup.backupId-or$restore.backupManifestSha256-cne$backup.manifestSha256-or$rehearsal.version-ne2-or$rehearsal.result-ne'PASS'-or$rehearsal.compatibilityMode-cne'LEGACY_BASELINE'-or$rehearsal.previousReleaseId-cne$baseline.releaseId-or$rehearsal.targetReleaseId-cne$target.releaseId-or$rehearsal.previousManifestSha256-cne(Hash $baselinePath)-or$rehearsal.targetManifestSha256-cne(Hash $targetManifestPath)-or$rehearsal.restoreEvidenceSha256-cne(Hash $restorePath)-or$rehearsal.previousMigrationDigest-cne$baseline.migrationDigest-or$rehearsal.targetMigrationDigest-cne$target.migrationDigest-or$rehearsal.previousBusinessBeforeDigest-cne$rehearsal.previousBusinessAfterDigest-or$rehearsal.previousBusinessBeforeDigest-cne$rehearsal.targetBusinessAfterDigest-or$digestInvalid-or-not$rehearsal.targetLegacyDataProjectionBeforeMigration-or-not$rehearsal.targetLegacyDataProjectionAfterMigration-or$rehearsal.actualLegacyCodeExecuted-or$rehearsal.rollbackCodeCompatible-or-not$rehearsal.databaseRestoreRequiredForRollback-or-not$rehearsal.legacyRestartRequiredForRollback-or-not$rehearsal.legacyLocalRoleMatrixNotClaimed-or$rehearsal.previousReleaseSmokeBeforeMigration-or$rehearsal.previousReleaseSmokeAfterMigration-or-not$rehearsal.targetMigrationsAppliedToIsolatedRestore-or-not$rehearsal.targetReleaseSmokeAfterMigration-or-not$rehearsal.authRoleMatrixVerified-or-not$rehearsal.businessKpiVerified-or-not$rehearsal.storageHashVerified-or-not$rehearsal.storageReferenceVerified-or-not$rehearsal.isolatedDatabaseCleaned-or-not$rehearsal.isolatedStorageCleaned-or$rehearsal.productionDatabaseMutated-or$backupAt-lt$quiesceAt-or$backupAt-gt$restoreAt-or($restoreAt-$backupAt).TotalHours-gt4-or($now-$backupAt).TotalHours-gt24-or$rehearsalAt-lt$restoreAt-or($now-$rehearsalAt).TotalDays-gt30){throw 'INITIAL_CUTOVER_COMPATIBILITY_REJECTED'}
$evidence=[ordered]@{version=5;result='PASS';proofType='initial-cutover-compatibility';generatorScriptSha256=(Hash $PSCommandPath);previousReleaseId=$baseline.releaseId;targetReleaseId=$target.releaseId;previousManifestSha256=(Hash $baselinePath);targetManifestSha256=(Hash $targetManifestPath);previousMigrationDigest=$baseline.migrationDigest;targetMigrationDigest=$target.migrationDigest;previousMigrationChainUnchanged=$true;additiveDeltaVerified=$true;previousReleaseSmokeBeforeMigration=$false;targetMigrationsAppliedToIsolatedRestore=$true;previousReleaseSmokeAfterMigration=$false;targetReleaseSmokeAfterMigration=$true;targetLegacyDataProjectionVerified=$true;actualLegacyCodeExecuted=$false;legacyLocalRoleMatrixNotClaimed=$true;originalProcessesQuiesced=$true;legacyQuiesceVerified=$true;quiesceEvidenceSha256=(Hash $quiescePath);rollbackMode='SIGNED_DATABASE_RESTORE_THEN_EXACT_LEGACY_RESTART';rollbackCodeCompatible=$false;backwardCompatible=$false;databaseRestoreRequiredForRollback=$true;legacyRestartRequiredForRollback=$true;restoreEvidenceSha256=(Hash $restorePath);restoreSigningKeyId=$restore.signingKeyId;rehearsalEvidenceSha256=(Hash $rehearsalPath);rehearsalSigningKeyId=$rehearsal.signingKeyId;latestBackupEvidenceSha256=(Hash $backupPath);backupId=$backup.backupId;backupManifestSha256=$backup.manifestSha256;freshBackupBound=$true;isolatedRestoreVerified=$true;authRoleMatrixVerified=$true;businessKpiVerified=$true;storageHashVerified=$true;storageReferenceVerified=$true;storageReferenceConversionVerified=$true;storageReferenceCount=$backup.storageReferenceCount;storageReferenceZeroVerified=$backup.storageReferenceZeroVerified;restoreTargetCleaned=$true;productionDatabaseMutated=$false;completedAt=$now.ToString('o')}
if($EvidenceOutputPath){if(Test-Path -LiteralPath $EvidenceOutputPath){throw 'INITIAL_CUTOVER_EVIDENCE_ALREADY_EXISTS'};[IO.File]::WriteAllText([IO.Path]::GetFullPath($EvidenceOutputPath),($evidence|ConvertTo-Json),(New-Object Text.UTF8Encoding($false)))}
$evidence|ConvertTo-Json
